const reg = /^(.+?)\1+$/
export class example extends plugin {
  constructor () {
    super({
      name: 'AQ：小功能',
      dsc: '小功能',
      event: 'message',
      priority: 500,
      rule: [
        {
          // 复读总开关：「复读开启 / 复读关闭」（全局，仅主人）
          reg: '^复读\\s*(开启|关闭|on|off)$',
          fnc: 'toggleFudu',
          permission: 'master'
        },
        {
          // 禁漫天堂：#jm 漫画ID（如 #jm 350234），jm 与 ID 中间需要空格
          reg: '^[/#]jm\\s+(\\d+)\\s*$',
          fnc: 'jmcomic'
        },
        {
          // 漏空格 / 格式不对时给个提示（#jm123、#jm 等）
          reg: '^[/#]jm(?!\\s+\\d)',
          fnc: 'jmHint'
        },
        {
          // 消息解剖台：引用一条消息后发「取/解剖」，输出其消息段结构与元信息（仅主人）
          reg: '^#?(取|解剖)$',
          fnc: 'dissect',
          permission: 'master'
        },
        {
          reg,
          fnc: 'fudu',
          log: false
        }
      ]
    })
  }

  // 复读开关（全局，写入 config.fudu，热生效，支持锅巴）
  async toggleFudu (e) {
    const arg = e.msg.trim().replace(/^复读\s*/, '').toLowerCase()
    const turnOn = arg === '开启' || arg === 'on'
    // 先取完整配置再写回，避免覆盖其它配置项
    const cfg = setting.getConfig('config') || {}
    cfg.fudu = turnOn
    setting.setConfig('config', cfg)
    await e.reply(turnOn ? '复读已开启，我会跟着你复读啦~' : '复读已关闭', true)
    return true
  }

  async fudu (e) {
    // 复读开关（默认关闭，可用「复读开启/关闭」或在锅巴/配置文件中开启）
    // 行为：消息由重复内容组成时叠加一节复读，如 11→111、1212→121212
    if (!setting.getConfig('config')?.fudu) return false
    if (e.user_id === e.self_id || /^(2854|3889)/.test(e.user_id)) return false
    e.reply(e.msg.replace(reg, '$&$1'))
    return false
  }

  // 格式提示：jm 与漫画ID 中间需要空格
  async jmHint (e) {
    await e.reply('格式：#jm 漫画ID（jm 和 ID 中间要有一个空格哦），例如：#jm 350234', true)
    return true
  }

  // 禁漫天堂：#jm 漫画ID，把整本下载为加密 PDF 发到群文件/私聊
  async jmcomic (e) {
    const m = e.msg.match(/^[/#]jm\s+(\d+)\s*$/)
    if (!m) return false
    const aid = m[1]

    // 用 jm.yaml 的最新配置刷新 CONFIG（锅巴修改 / 手改配置文件均热生效）
    Object.assign(CONFIG, setting.getConfig('jm') || {})
    if (!CONFIG.AVS) {
      await e.reply('未配置禁漫账号 AVS，请在锅巴「AQing-plugin → 禁漫天堂」或 config/config/jm.yaml 中填写 AVS 后再试~', true)
      return true
    }

    await e.reply(`开始下载本子 ${aid}，请稍候…`, true)
    try {
      const file = await new ComicPDFGenerator().create(aid)
      const filePath = path.join(path.resolve(), file)
      const target = e.isGroup ? e.group : e.friend
      const sendFile = e.isGroup ? (e.group.sendFile || e.group.fs?.upload) : e.friend.sendFile
      if (sendFile) {
        await sendFile.call(target, filePath)
      } else {
        await e.reply('当前适配器不支持发送文件，无法上传 PDF')
      }
      await fs.unlink(file).catch(err => logger.error('[禁漫天堂] 文件清理失败：', err))
    } catch (err) {
      await e.reply(err?.message || String(err))
      logger.error('[禁漫天堂]', err)
    }
    return true
  }

  // 消息解剖台：引用一条消息后发「取/解剖」，输出其结构（仅主人）
  // 走 Yunzai 通用接口 e.getReply()（OneBotv11 用 get_msg 拉取），
  // 因此 NapCat / Lagrange / go-cqhttp 等 OneBot 适配器以及 icqq 均可用。
  async dissect (e) {
    if (!e.reply_id || typeof e.getReply !== 'function') {
      return e.reply('请先引用（回复）一条消息，再发送「取/解剖」')
    }

    let source
    try {
      source = await e.getReply()
    } catch (err) {
      logger.error('[消息解剖] 获取被引用消息失败', err)
      return e.reply('❌ 获取被引用消息失败：' + (err?.message || err))
    }
    if (!source) return e.reply('❌ 找不到目标消息（适配器未返回，或消息已过期）')

    try {
      // 消息段分解：parseMsg 后每段形如 { type, ...字段 }
      const segments = Array.isArray(source.message) ? source.message : []
      const parsedSegments = segments.map((seg, index) => ({
        index,
        type: seg?.type || 'unknown',
        data: this.simplifySeg(seg)
      }))

      // 元信息：剥掉冗长的 message / raw_message 后单独展示
      const { message, raw_message, ...meta } = source

      const report = [
        '📋 消息解析结果',
        `消息ID：${e.reply_id}`,
        '【元信息】',
        JSON.stringify(meta, null, 2),
        '【消息段分解】',
        ...(parsedSegments.length ? parsedSegments.map(o => JSON.stringify(o, null, 2)) : ['（无消息段）'])
      ]
      if (raw_message != null) report.push('【原始 CQ 码】', String(raw_message))

      return e.reply(await common.makeForwardMsg(e, report))
    } catch (err) {
      logger.error('[消息解析失败]', err)
      return e.reply('❌ 消息解析失败')
    }
  }

  // 简化单个消息段：过长字符串 / 二进制字段打码，避免刷屏
  simplifySeg (seg) {
    if (!seg || typeof seg !== 'object') return seg
    const out = {}
    for (const [k, v] of Object.entries(seg)) {
      if (k === 'type') continue
      if (Buffer.isBuffer(v)) out[k] = `[二进制数据 ${v.length} 字节]`
      else if (typeof v === 'string' && v.length > 512) out[k] = `[超长内容 ${v.length} 字符]`
      else out[k] = v
    }
    return out
  }
}
